pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, uint256 bal, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        bal = bound(bal, 0, type(uint256).max / 2);
        amount = bound(amount, bal + 1, type(uint256).max);
        vm.deal(address(c), bal);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
